draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // head
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.lineWidth = 3;
  ctx.stroke();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2, H/2 + 150);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 - 50, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 + 50, H/2 + 70);
  ctx.stroke();

  // hands
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 + 70, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + 70, 10, 0, 2*Math.PI);
  ctx.fill();

  // stop sign
  ctx.fillStyle = '#ff0000';
  ctx.globalAlpha = 0.5;
  ctx.beginPath();
  ctx.rect(W/2 - 75, H/2 - 50, 150, 150);
  ctx.fill();
  ctx.globalAlpha = 1;
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.font = '50px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('NO', W/2, H/2 + 25);

  // heart
  ctx.fillStyle = '#ff69b4';
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 100 + 50*Math.sin(t), 20, 0, 2*Math.PI);
  ctx.fill();

  ctx.restore();
}
